window.__WB_TEXTBOOK__ = [{"id": "cod_riscv", "name": "计算机组成与设计：硬件/软件接口（RISC-V版）", "author": "David A. Patterson, John L. Hennessy", "level": "核心必修 · 体系结构基石", "chapters": [{"cid": "arch_ch1", "title": "第1章 计算机抽象与技术：性能铁律、阿姆达尔定律与功耗墙", "summary": "本章奠定计算机系统定量分析的基石，核心围绕性能度量与物理约束展开。CPU执行时间由“性能铁律”决定：$T_{CPU} = IC \\times CPI \\times T_{clk} = \\frac{IC \\times CPI}{f_{clk}}$，其中指令数 $IC$ 取决于算法与指令集（ISA），$CPI$ 取决于微架构与访存效率，$T_{clk}$ 受限于关键路径。多核并行分析中，Amdahl 定律指出若可并行比例为 $f$、加速比为 $S$，则整体加速比 $Speedup = \\frac{1}{(1 - f) + f / S}$，揭示了串行瓶颈对扩展性的限制。随着 Dennard 缩放失效，动态功耗 $P_{dyn} = \\frac{1}{2} C V^2 f$ 撞上“功耗墙”，迫使架构转向多核低频与专用加速器。", "template_cpp": "// 性能铁律与 Amdahl 定律定量评估模板\n#include <iostream>\nusing namespace std;\n\ndouble cpu_time(long long ic, double cpi, double freq_ghz) {\n    return (ic * cpi) / (freq_ghz * 1e9);\n}\n\ndouble amdahl_speedup(double parallel_frac, double s) {\n    return 1.0 / ((1.0 - parallel_frac) + parallel_frac / s);\n}\n\ndouble mips_rating(double freq_mhz, double cpi) {\n    return freq_mhz / cpi;\n}", "pitfalls": "1. 误用主频直接比较不同 ISA 或微架构处理器的性能，忽略 $IC$ 与 $CPI$ 的耦合变化；2. 计算加权平均 $CPI$ 时错把指令执行时间占比当成指令条数占比；3. 应用 Amdahl 定律时将“并行后时间占比”误代为“原始串行程序中的可并行比例 $f$”。", "workbench_tags": ["性能铁律", "Amdahl定律", "功耗墙", "加权CPI"], "problems": [{"oj": "教材精选题", "pid": "COD-1.1", "title": "双编译器指令数与 CPI 权衡计算", "diff": "基础", "hint": "破题思路：直接利用 CPU 时间公式 $T = IC \\times CPI / f$。\n解答要点：设时钟频率 $f = 4\\text{ GHz}$（即 $T_{clk} = 0.25\\text{ ns}$）。编译器 A：$IC_A = 1.0 \\times 10^9$，$CPI_A = 1.1$，则 $T_A = 1.0 \\times 10^9 \\times 1.1 \\times 0.25\\text{ ns} = 0.275\\text{ s}$。编译器 B：$IC_B = 1.2 \\times 10^9$，$CPI_B = 0.9$，则 $T_B = 1.2 \\times 10^9 \\times 0.9 \\times 0.25\\text{ ns} = 0.270\\text{ s}$。虽然 B 的指令数更多，但因其平均 $CPI$ 更低，整体执行时间更短，加速比为 $0.275 / 0.270 \\approx 1.0185$。"}, {"oj": "教材精选题", "pid": "COD-1.2", "title": "Amdahl 定律与目标加速比反推", "diff": "中档", "hint": "破题思路：某程序总执行时间为 $100\\text{ s}$，其中乘法指令占 $80\\text{ s}$（$f = 0.8$），希望整体运行时间降至 $25\\text{ s}$（即总加速比 $Speedup = 4$）。\n解答要点：代入 Amdahl 公式 $4 = \\frac{1}{(1 - 0.8) + 0.8 / S} = \\frac{1}{0.2 + 0.8 / S}$，解得 $0.2 + 0.8 / S = 0.25 \\implies 0.8 / S = 0.05 \\implies S = 16$。若目标加速比为 $6$（即耗时 $16.67\\text{ s}$），由于串行部分就占 $20\\text{ s} > 16.67\\text{ s}$，即使 $S \\to \\infty$ 也无法实现。"}, {"oj": "教材精选题", "pid": "COD-1.3", "title": "动态功耗墙与电压-频率联合缩放", "diff": "中档", "hint": "破题思路：动态功耗满足 $P \\propto C \\cdot V^2 \\cdot f$，在电容负载 $C$ 缩小 15% 时同时降低电压与频率。\n解答要点：设原功耗为 $P_0 = C_0 V_0^2 f_0$。若新工艺电容 $C_1 = 0.85 C_0$，电压降为 $V_1 = 0.85 V_0$，频率保持不变 $f_1 = f_0$，则新功耗比值 $\\frac{P_1}{P_0} = 0.85 \\times (0.85)^2 \\times 1 = 0.85^3 \\approx 0.614$，功耗降低约 $38.6\\%$。若同时将频率提升至 $1.2 f_0$，则功耗变为 $0.614 \\times 1.2 \\approx 0.737 P_0$。"}, {"oj": "教材精选题", "pid": "COD-1.4", "title": "多核处理器串行瓶颈与能效最优核数", "diff": "压轴", "hint": "破题思路：给定程序并行度 $f = 0.9$，单核频率为 $f_0$、功耗为 $P_0$；转向 $N$ 核时每核降频降压至 $V' = 0.8 V_0, f' = 0.7 f_0$。\n解答要点：性能加速比为 $S(N) = \\frac{0.7}{(1 - 0.9) + 0.9 / N} = \\frac{0.7}{0.1 + 0.9/N}$。总功耗为 $P(N) = N \\cdot (0.8)^2 \\cdot 0.7 P_0 = 0.448 N P_0$。当 $N=4$ 时，$S(4) = 0.7 / 0.325 \\approx 2.15$，$P(4) = 1.792 P_0$；当 $N=16$ 时，$S(16) = 0.7 / 0.15625 \\approx 4.48$，$P(16) = 7.168 P_0$。可见盲目堆核会导致能效比（$S(N)/P(N)$）急剧下降。"}]}, {"cid": "arch_ch2", "title": "第2章 RISC-V 指令集架构：编码格式、寻址与过程调用", "summary": "本章系统剖析 RISC-V RV32I/RV64I 精简指令集的设计哲学：固定 32 位指令字长、规整的 32 个通用寄存器（`x0` 恒为 0）以及 Load-Store 访存架构。六种基本指令格式（R/I/S/B/U/J）在硬件译码上高度对称，源寄存器 `rs1`、`rs2` 与目的寄存器 `rd` 位置固定，且 B 型与 J 型指令的立即数位序经过特殊重排以保持符号位 `inst[31]` 在最高位并实现 2 字节对齐跳转。过程调用严格遵循 ABI 约定：`a0-a7` 传递参数与返回值，`ra`（`x1`）保存返回地址，`sp`（`x2`）指向栈顶且需按 16 字节对齐；叶过程可直接使用临时寄存器 `t0-t6`，非叶过程必须在栈上保存 `ra` 与被调用者保存寄存器 `s0-s11`。", "template_cpp": "# RISC-V 递归阶乘过程调用标准汇编模板 (RV32I)\nfact:\n    addi sp, sp, -8      # 分配栈帧保存 ra 和 a0\n    sw   ra, 4(sp)\n    sw   a0, 0(sp)\n    addi t0, x0, 1\n    bgt  a0, t0, L_rec   # if (n > 1) goto L_rec\n    addi a0, x0, 1       # return 1\n    addi sp, sp, 8\n    jalr x0, 0(ra)\nL_rec:\n    addi a0, a0, -1      # n - 1\n    jal  ra, fact        # 递归调用 fact(n-1)\n    lw   t1, 0(sp)       # 恢复原 n\n    lw   ra, 4(sp)       # 恢复返回地址\n    addi sp, sp, 8\n    mul  a0, t1, a0      # a0 = n * fact(n-1)\n    jalr x0, 0(ra)", "pitfalls": "1. B 型与 J 型指令立即数默认左移 1 位（最低位隐含 0），手工编码时忘记将字节偏移量除以 2；2. `lui` 加载高 20 位后紧跟 `addi` 加载低 12 位时，若低 12 位最高位为 1（符号扩展为负数），高 20 位必须提前加 1；3. 非叶函数调用子函数前忘记压栈保存 `ra`，导致 `jalr` 陷入死循环。", "workbench_tags": ["RISC-V指令编码", "过程调用ABI", "PC相对寻址", "栈帧管理"], "problems": [{"oj": "教材精选题", "pid": "COD-2.1", "title": "RISC-V 32位大常数加载与 lui/addi 符号修正", "diff": "基础", "hint": "破题思路：将 32 位立即数 `0x12345800` 拆分为高 20 位与 12 位有符号立即数。\n解答要点：低 12 位为 `0x800`，作为 12 位有符号数其最高位为 1，符号扩展后等价于 $-2048$（即 `0xFFFFF800`）。若高 20 位直接写 `0x12345`，相加结果为 `0x12345000 - 0x800 = 0x12344800`，少了 $2^{12}$。因此必须对高 20 位加 1：`lui x10, 0x12346`，再执行 `addi x10, x10, -2048`（即 `0x800`），最终 `0x12346000 + 0xFFFFF800 = 0x12345800`。"}, {"oj": "教材精选题", "pid": "COD-2.2", "title": "B 型条件分支指令机器码手工编码", "diff": "中档", "hint": "破题思路：编码 `beq x5, x6, Loop`，假设 `beq` 当前地址为 `0x1010`，`Loop` 地址为 `0x1000`。\n解答要点：相对偏移量 `offset = 0x1000 - 0x1010 = -16`，13 位二进制补码为 `1_1111_1111_0000`（`imm[12:0]`）。按 B 型格式拆分：`imm[12]=1`，`imm[10:5]=111111`，`rs2=6 (00110)`，`rs1=5 (00101)`，`funct3=000`，`imm[4:1]=1000`，`imm[11]=1`，`opcode=1100011`。拼接 32 位机器码为 `1111111_00110_00101_000_10001_1100011`，即 `0xFE6288E3`。"}, {"oj": "教材精选题", "pid": "COD-2.3", "title": "非叶过程调用寄存器保存与栈空间最小化", "diff": "中档", "hint": "破题思路：C 函数 `int f(int a, int b)` 调用 `g(a+b)` 后再返回 `a + g(a+b)`，分析 `s0` 与 `t0` 的使用策略。\n解答要点：`a` 初始在 `a0` 中，因调用 `g` 会覆盖 `a0`（调用者保存寄存器），必须在调用 `g` 前将 `a` 存入栈或先保存旧 `s0` 后将 `a` 放入 `s0`。总栈帧只需保存 `ra` 和 `s0`（8 字节，若按 RV ABI 16 字节对齐则分配 16 字节），避免在递归深度大时浪费栈空间。"}, {"oj": "教材精选题", "pid": "COD-2.4", "title": "数组指针遍历 vs 下标索引的指令级优化", "diff": "压轴", "hint": "破题思路：对比 `for(i=0; i<n; i++) a[i]=0;` 与指针版本 `for(p=a; p<&a[n]; p++) *p=0;` 在 RV64I 中的指令数。\n解答要点：下标版每次迭代需执行 `slli t1, t0, 3`（乘 8）、`add t2, a0, t1`、`sd x0, 0(t2)`、`addi t0, t0, 1`、`blt t0, a1, loop` 共 5 条指令；指针版将乘 8 移出循环（强度削弱），循环体内仅需 `sd x0, 0(t0)`、`addi t0, t0, 8`、`bltu t0, t2, loop` 共 3 条指令，动态指令数减少 $40\\%$。"}]}, {"cid": "arch_ch3", "title": "第3章 计算机算术：补码溢出、硬件乘除法与 IEEE 754 浮点", "summary": "本章解析数字逻辑层面的算术运算实现与精度边界。有符号整数采用二进制补码表示，加减法共用同一加法器，通过双符号位或最高位进位与次高位进位异或（$C_{in} \\oplus C_{out}$）判断溢出，而无符号数溢出直接看进位/借位。硬件乘法器从基础的“移位-相加”迭代演进至 Booth 算法与 Wallace 树并行乘法器；除法器则通过恢复余数或不恢复余数法逐位生成商。浮点数遵循 IEEE 754 标准，单精度 32 位由 1 位符号、8 位阶码（偏置 127）与 23 位尾数（隐含前导 1）组成；浮点加法需经历对阶、尾数加减、规格化与舍入（保护位 Guard、舍入位 Round、粘滞位 Sticky），由此揭示了浮点加法不满足结合律的本质。", "template_cpp": "// IEEE 754 单精度浮点数位域解析模板\n#include <cstdint>\n#include <iostream>\nusing namespace std;\n\nvoid decode_fp32(float x) {\n    uint32_t bits = *reinterpret_cast<uint32_t*>(&x);\n    uint32_t sign = (bits >> 31) & 1;\n    int32_t  exp  = ((bits >> 23) & 0xFF) - 127;\n    uint32_t frac = bits & 0x7FFFFF;\n    cout << \"S=\" << sign << \" E=\" << exp << \" Frac=0x\" << hex << frac << endl;\n}", "pitfalls": "1. 误认为补码减法 $A - B$ 溢出判断直接看进位，实则需将 $B$ 取反加 1 转化为加法后比较最高位进位与符号位；2. IEEE 754 非规格化数（阶码全 0）的隐含前导位是 `0` 而非 `1`，且真实指数为 $1 - 127 = -126$ 而非 $-127$；3. 浮点舍入默认采用“向偶数舍入”（Round to Nearest Even），在 `0.5` 中点处看最低有效位奇偶性。", "workbench_tags": ["补码溢出", "Booth乘法", "IEEE754浮点", "保护位与粘滞位"], "problems": [{"oj": "教材精选题", "pid": "COD-3.1", "title": "IEEE 754 单精度浮点数的十六进制与十进制互转", "diff": "基础", "hint": "破题思路：将十进制 $-0.75$ 转换为 IEEE 754 单精度十六进制表示。\n解答要点：$-0.75 = -3/4 = -1.5 \\times 2^{-1} = -(1.1)_2 \\times 2^{-1}$。符号位 $S = 1$；阶码 $E = -1 + 127 = 126 = (01111110)_2$；尾数小数部分 `frac` 为 `1000...0`（23 位）。拼接得 `1_01111110_10000000000000000000000`，每 4 位一组为 `0xBF400000`。"}, {"oj": "教材精选题", "pid": "COD-3.2", "title": "带 Guard/Round/Sticky 位的浮点加法精度舍入", "diff": "中档", "hint": "破题思路：设尾数仅保留 4 位有效数字（含前导 1），计算 $1.000_2 \\times 2^3 + 1.111_2 \\times 2^{-1}$，含 G/R/S 三位。\n解答要点：大阶向小阶对齐时将小阶数右移 $3 - (-1) = 4$ 位：$1.111_2 \\times 2^{-1} = 0.0001111_2 \\times 2^3$。保留 3 位保护位后：有效位为 `0.000`，`G=1, R=1, S=1`（因第 4 位移出的 1 置位 Sticky）。相加得 `1.000` 附带 `GRS = 111`。由于 `GRS > 100`（超过半个 ULP），向最近偶数舍入直接进 1，结果为 $1.001_2 \\times 2^3$。"}, {"oj": "教材精选题", "pid": "COD-3.3", "title": "4位有符号数 Booth 乘法逐拍状态追踪", "diff": "中档", "hint": "破题思路：用 4 位 Booth 算法计算 $(-5) \\times (-3)$，即乘数 $Q = 1101$，被乘数 $M = 1011$（$-M = 0101$），初态 $(A, Q, Q_{-1}) = (0000, 1101, 0)$。\n解答要点：拍 1：`Q0Q_{-1}=10`，减 $M$（加 `0101`）得 $A=0101$，算术右移得 `(0010, 1110, 1)`；拍 2：`01`，加 $M$（`1011`）得 $A=1101$，算术右移得 `(1110, 1111, 0)`；拍 3：`10`，减 $M$ 得 $A=0011$，右移得 `(0001, 1111, 1)`；拍 4：`11` 不操作，右移得 `(0000, 1111, 1)`。结果 `0000_1111 = +15`。"}, {"oj": "教材精选题", "pid": "COD-3.4", "title": "浮点加法结合律失效的构造与验证", "diff": "压轴", "hint": "破题思路：利用单精度最大指数与小数吞噬效应构造 $(A + B) + C \\neq A + (B + C)$。\n解答要点：令 $A = -1.5 \\times 2^{30}, B = 1.5 \\times 2^{30}, C = 1.0$。计算 $(A + B) + C = 0 + 1.0 = 1.0$；而计算 $A + (B + C)$ 时，由于 $B$ 与 $C$ 阶码相差 $30$，而单精度尾数仅 24 位精度，$C$ 在对阶右移时被彻底舍入为 0，故 $B + C = B$，最终 $A + (B + C) = A + B = 0.0 \\neq 1.0$。"}]}, {"cid": "arch_ch4", "title": "第4章（上）单周期处理器数据通路与控制信号设计", "summary": "本章构建完整的 RISC-V 单周期处理器，所有指令均在一个时钟周期内完成取指、译码、执行、访存与写回。数据通路包含指令存储器（IMEM）、寄存器堆（两读一写）、立即数生成器（ImmGen）、算术逻辑单元（ALU）、数据存储器（DMEM）及多路选择器。主控制器根据 7 位 `opcode` 生成 `Branch`、`MemRead`、`MemtoReg`、`ALUOp`、`MemWrite`、`ALUSrc`、`RegWrite` 等控制信号；二级译码器 `ALUControl` 结合 `ALUOp` 与指令的 `funct3`/`funct7` 输出 4 位 ALU 操作码。由于所有指令共用同一时钟周期，单周期时钟周期长度受限于最慢指令（通常是 `ld`/`lw`）的组合逻辑关键路径总延迟，导致硬件资源无法复用且整体频率受限。", "template_cpp": "// RISC-V 单周期主控制器真值表逻辑 (C++ 仿真片段)\nstruct CtrlSig { bool ALUSrc, MemtoReg, RegWrite, MemRead, MemWrite, Branch; int ALUOp; };\nCtrlSig main_control(int opcode) {\n    switch(opcode) {\n        case 0b0110011: return {0, 0, 1, 0, 0, 0, 2}; // R-type\n        case 0b0000011: return {1, 1, 1, 1, 0, 0, 0}; // lw/ld\n        case 0b0100011: return {1, 0, 0, 0, 1, 0, 0}; // sw/sd\n        case 0b1100011: return {0, 0, 0, 0, 0, 1, 1}; // beq\n        default:        return {0, 0, 0, 0, 0, 0, 0};\n    }\n}", "pitfalls": "1. `sw`/`sd` 和 `beq` 指令不写回寄存器堆（`RegWrite=0`），此时 `MemtoReg` 信号属于无关项（Don't Care `X`），不可误写为固定值影响化简；2. 误把 `beq` 跳转目标计算与 ALU 比较混用同一个加法器，实际上必须配备独立的 `PC + imm` 加法器；3. 计算关键路径延迟时错把各阶段延迟相加而非取并行分支的最大值（如 `ImmGen` 与 `RegRead` 并行）。", "workbench_tags": ["单周期数据通路", "主控制单元", "ALUControl", "关键路径延迟"], "problems": [{"oj": "教材精选题", "pid": "COD-4.1", "title": "单周期关键路径延迟与最高主频计算", "diff": "基础", "hint": "破题思路：已知各部件延迟：`IMEM=200ps, RegRead=100ps, ImmGen=30ps, Mux=20ps, ALU=120ps, DMEM=200ps, RegWrite=100ps`。\n解答要点：R 型指令耗时 `200+100+20+120+20+100=560ps`；`lw` 指令需经过 `IMEM(200) -> max(RegRead(100), ImmGen(30)+Mux(20)) -> ALU(120) -> DMEM(200) -> Mux(20) -> RegWrite(100)`，总延迟为 `200+100+120+200+20+100 = 740ps`。故最短时钟周期为 `740ps`，最高主频 $f_{max} = 1 / 740\\text{ ps} \\approx 1.35\\text{ GHz}$。"}, {"oj": "教材精选题", "pid": "COD-4.2", "title": "控制信号故障诊断（Stuck-at-0/1 故障）", "diff": "中档", "hint": "破题思路：若主控制器的 `ALUSrc` 信号线因硬件故障恒固定为 `0`（Stuck-at-0），分析哪些指令失效。\n解答要点：`ALUSrc=0` 意味着 ALU 第二个操作数恒来自寄存器 `rs2` 而非立即数 `ImmGen`。因此所有依赖 `ALUSrc=1` 的指令（`lw`、`sw`、`addi` 等 I/S 型指令）均无法正确计算偏移地址或立即数，而 R 型指令和 `beq`（均需 `ALUSrc=0`）仍可正常执行。"}, {"oj": "教材精选题", "pid": "COD-4.3", "title": "扩展支持 jal 指令的数据通路与控制改造", "diff": "中档", "hint": "破题思路：`jal rd, offset` 需要同时完成 `rd = PC + 4` 和 `PC = PC + imm`。\n解答要点：数据通路需在写回端 `MemtoReg` 多路器扩展为三选一，新增输入 `PC + 4`；在 PC 更新端多路器新增由 `Jump` 信号控制的分支，直接接收 J 型立即数与 `PC` 相加的结果。控制信号设置：`Jump=1, RegWrite=1, MemtoReg=2(PC+4), MemWrite=0, Branch=0`。"}, {"oj": "教材精选题", "pid": "COD-4.4", "title": "单周期与理想多周期性能对比权衡", "diff": "压轴", "hint": "破题思路：若将上述单周期改造成 5 步非流水线多周期处理器（每步周期取最慢部件 `200ps`），指令分布为 `lw 25%, sw 10%, R 45%, beq 20%`。\n解答要点：各指令所需周期数：`lw=5, sw=4, R=4, beq=3`。加权平均 $CPI = 0.25\\times 5 + 0.10\\times 4 + 0.45\\times 4 + 0.20\\times 3 = 1.25 + 0.40 + 1.80 + 0.60 = 4.05$。多周期平均耗时 $4.05 \\times 200\\text{ ps} = 810\\text{ ps}$，反而慢于单周期的 $740\\text{ ps}$，说明拆分为多周期若不引入流水线反而可能因木桶效应与段间开销降低性能。"}]}, {"cid": "arch_ch5", "title": "第4章（下）流水线处理器：冒险检测、数据前递与分支预测", "summary": "本章将单周期拆分为 IF、ID、EX、MEM、WB 五级流水线，通过级间寄存器隔离实现指令级并行，理想吞吐率提升至单周期的 5 倍。然而流水线面临三大冒险：结构冒险（通过哈佛分离存储与前半周期写/后半周期读寄存器解决）、数据冒险（RAW 写后读依赖）与控制冒险（分支指令改变 PC）。前递单元（Forwarding Unit）可将 EX/MEM 与 MEM/WB 级间寄存器中的最新结果直接旁路回 ALU 输入端，消除大部分算术数据冒险；唯有 Load-Use 冒险因数据在 MEM 末尾才就绪，必须由冒险检测单元插入 1 个气泡（Stall）并冻结 PC 与 IF/ID。控制冒险则通过分支预测（静态预测不跳转、1-bit/2-bit 饱和计数器及 BTB）与提前在 ID 级判断相等来降低惩罚周期。", "template_cpp": "// EX 级前递单元 (Forwarding Unit) 与 Load-Use 冒险检测逻辑\nif (EX_MEM.RegWrite && EX_MEM.rd != 0 && EX_MEM.rd == ID_EX.rs1) ForwardA = 0b10;\nelse if (MEM_WB.RegWrite && MEM_WB.rd != 0 && MEM_WB.rd == ID_EX.rs1) ForwardA = 0b01;\nelse ForwardA = 0b00;\n\n// Load-Use 冒险检测 (ID 级插入 1 个 Stall 气泡)\nbool stall = (ID_EX.MemRead && (ID_EX.rd == IF_ID.rs1 || ID_EX.rd == IF_ID.rs2) && ID_EX.rd != 0);", "pitfalls": "1. 前递优先级混淆：当 EX/MEM 与 MEM/WB 同时匹配 `rs1` 时，必须优先选择较新的 EX/MEM（`ForwardA=10`）；2. 忘记判断 `rd != 0`（`x0` 寄存器恒为 0，绝不可前递非零计算结果）；3. 误以为 Load-Use 后面紧跟 `sw` 的存储数据（`rs2`）也需要 Stall，实际上 `sw` 的存储值在 MEM 级才使用，可通过 MEM-to-MEM 旁路免除停顿。", "workbench_tags": ["五级流水线", "数据前递", "Load-Use停顿", "2-bit分支预测"], "problems": [{"oj": "教材精选题", "pid": "COD-5.1", "title": "汇编序列 RAW 依赖识别与无前递/有前递周期数对比", "diff": "基础", "hint": "破题思路：序列：`1: lw x1, 0(x2); 2: add x3, x1, x4; 3: sub x5, x3, x6; 4: or x7, x3, x8`。\n解答要点：在全前递（且寄存器前半周期写、后半周期读）的 5 级流水线中：指令 1 与 2 存在 Load-Use 依赖，必须在指令 2 的 ID 级插入 1 个气泡（Stall），之后 `MEM/WB -> EX` 前递 `x1`；指令 2 与 3、4 间的 `x3` 分别通过 `EX/MEM -> EX` 和 `MEM/WB -> EX` 前递消除停顿。4 条指令总耗时 $5 + (4-1) + 1 = 9$ 个周期。"}, {"oj": "教材精选题", "pid": "COD-5.2", "title": "编译器指令调度消除 Load-Use 停顿", "diff": "中档", "hint": "破题思路：给定 `lw x1, 0(x10); lw x2, 8(x10); add x3, x1, x2; sw x3, 16(x10); lw x4, 24(x10); add x5, x4, x6`，通过重排减少气泡。\n解答要点：原始顺序在 `(x2 -> add)` 与 `(x4 -> add)` 处各产生 1 个气泡。可将无依赖的 `lw x4, 24(x10)` 提前至 `lw x2` 之后、`add x3` 之前，使 `x2` 有足够间隔；同理将 `sw x3, 16(x10)` 插在 `lw x4` 与 `add x5` 之间，彻底消除全部 2 个 Load-Use 气泡。"}, {"oj": "教材精选题", "pid": "COD-5.3", "title": "2-bit 饱和分支预测器状态转移与准确率计算", "diff": "中档", "hint": "破题思路：循环分支模式为 `T, T, T, N` 重复（`T`=跳转，`N`=不跳），2-bit 预测器初态为强不跳（`00`），状态 `00/01` 预测 `N`，`10/11` 预测 `T`。\n解答要点：第 1 轮：`00(猜N)->实际T`错，转 `01`；`01(猜N)->T`错，转 `10`；`10(猜T)->T`对，转 `11`；`11(猜T)->N`错，转 `10`。第 2 轮起稳态进入 `10 -> 11 -> 11 -> 10` 循环，每 4 次仅在最后的 `N` 处错 1 次，稳态预测准确率为 $75\\%$（1-bit 预测器在此模式每次都会错两次，准确率仅 $50\\%$）。"}, {"oj": "教材精选题", "pid": "COD-5.4", "title": "精确异常（Precise Exception）在五级流水线中的冲刷机制", "diff": "压轴", "hint": "破题思路：假设第 3 条指令在 EX 级发生算术溢出异常，同时流水线中第 1、2 条在 WB/MEM，第 4、5 条在 ID/IF。\n解答要点：为保证精确异常，硬件必须让第 1、2 条正常写回完成，同时将 `EX/MEM`、`ID/EX`、`IF/ID` 控制信号全部清零（插入 NOP 气泡）以阻止第 3、4、5 条修改寄存器或内存；将异常指令 PC 写入 `SEPC`，原因写入 `SCAUSE`，并将 PC 强制跳转至操作系统异常处理入口 `0x80000180`。"}]}, {"cid": "arch_ch6", "title": "第5章（上）存储器层次结构：Cache 映射、替换与写策略", "summary": "利用时间与空间局部性，存储器层次结构以 SRAM Cache 弥合处理器与主存间的“存储墙”鸿沟。物理地址由低到高划分为块内偏移（Offset）、组索引（Index）与标记（Tag）。直接映射易发生冲突失效；$N$ 路组相联降低冲突但需并行 Tag 比较器与 LRU/FIFO 替换；全相联消除组冲突但硬件开销极大。Cache 失效分为强制、容量与冲突三类（3C 模型）。写命中采用写直达（配写缓冲）或写回（需脏位 Dirty Bit）；核心性能指标为平均访存时间：$AMAT = T_{hit} + MissRate \\times MissPenalty$。", "template_cpp": "// Cache 地址拆分与 AMAT 计算模板\nstruct CacheAddr {\n    uint32_t tag, index, offset;\n};\nCacheAddr split_addr(uint32_t addr, int offset_bits, int index_bits) {\n    uint32_t offset = addr & ((1u << offset_bits) - 1);\n    uint32_t index  = (addr >> offset_bits) & ((1u << index_bits) - 1);\n    uint32_t tag    = addr >> (offset_bits + index_bits);\n    return {tag, index, offset};\n}", "pitfalls": "1. 计算 Cache 总比特容量时漏算 Valid 位、Dirty 位（Write-Back 时）以及 Tag 位阵列；2. 混淆“字地址”与“字节地址”，导致 Offset 位数算错；3. 误以为增大 Cache 块大小（Block Size）总能降低失效率，实际上块过大在总容量不变时会减少组数，反而加剧冲突失效并拉高 Miss Penalty。", "workbench_tags": ["Cache映射", "3C失效模型", "Write-Back", "AMAT平均访存时间"], "problems": [{"oj": "教材精选题", "pid": "COD-6.1", "title": "32位地址下四路组相联 Cache 位宽与总硬件容量计算", "diff": "基础", "hint": "破题思路：32 位字节地址，数据容量 $64\\text{ KiB}$，4 路组相联，块大小 $64\\text{ B}$，采用写回法（1 位 Dirty + 1 位 Valid，2 位 LRU）。\n解答要点：块数 $N = 64\\text{ KiB} / 64\\text{ B} = 1024$；组数 $S = 1024 / 4 = 256 = 2^8$。故 `Offset = 6 bits`，`Index = 8 bits`，`Tag = 32 - 6 - 8 = 18 bits`。每块开销位 $= 1 + 1 + 2 + 18 = 22\\text{ bits}$，数据位 $= 64 \\times 8 = 512\\text{ bits}$。总容量 $= 1024 \\times (512 + 22) = 546,816\\text{ bits} \\approx 66.75\\text{ KiB}$。"}, {"oj": "教材精选题", "pid": "COD-6.2", "title": "访存序列在直接映射与两路组相联（LRU）下的命中追踪", "diff": "中档", "hint": "破题思路：Cache 共 4 块（每块 1 字），字地址序列：`0, 8, 0, 6, 8`。\n解答要点：直接映射（`index = addr % 4`）：`0`(Miss, 0号位存0), `8`(Miss, `8%4=0` 替换0为8), `0`(Miss, 替换8为0), `6`(Miss, `6%4=2` 存6), `8`(Miss, 替换0为8)，共 0 次命中。2 路组相联（2 组，每组 2 路，`index = addr % 2`）：`0`(Miss, 组0=[0]), `8`(Miss, 组0=[0,8]), `0`(Hit, 组0=[8,0]), `6`(Miss, 组1=[6]), `8`(Hit, 组0=[0,8])，命中 2 次。"}, {"oj": "教材精选题", "pid": "COD-6.3", "title": "两级 Cache（L1+L2）的全局失效率与 AMAT 计算", "diff": "中档", "hint": "破题思路：L1 命中耗时 1 周期，局部失效率 5%；L2 命中耗时 10 周期，局部失效率 20%；主存惩罚 100 周期。\n解答要点：利用嵌套公式 $AMAT = T_{L1} + MR_{L1} \\times (T_{L2} + MR_{L2} \\times Penalty_{Mem}) = 1 + 0.05 \\times (10 + 0.20 \\times 100) = 1 + 0.05 \\times 30 = 2.5$ 周期。L2 全局失效率 $= 0.05 \\times 0.20 = 1\\%$。"}, {"oj": "教材精选题", "pid": "COD-6.4", "title": "矩阵行优先与列优先遍历对 Cache 失效率及 CPI 的影响", "diff": "压轴", "hint": "破题思路：$1024 \\times 1024$ 的 `double`（8B）矩阵，L1 Cache $32\\text{ KiB}$，块大小 $64\\text{ B}$（每块 8 个 `double`）。\n解答要点：行优先访问步长为 1，每 8 次访问触发 1 次强制失效，失效率 $12.5\\%$；列优先步长为 $1024 \\times 8 = 8192\\text{ B}$，每访问 1 个元素跳跨 128 个 Cache 块，Cache 总共才 $32\\text{ KiB}/64\\text{ B} = 512$ 块，远小于一列所需的 1024 块，导致每一列访问后前序缓存块全部被逐出，失效率高达 $100\\%$，访存停顿周期暴增 8 倍。"}]}, {"cid": "arch_ch7", "title": "第5章（下）虚拟内存与 TLB：页表结构、快表与 VIPT 协同", "summary": "虚拟内存为每个进程提供独立且连续的虚拟地址空间，并与操作系统协同实现内存保护与按需分页。虚拟地址分为虚拟页号（VPN）与页内偏移（Page Offset）；页表（Page Table）维护 VPN 到物理页号（PPN）的映射，并附带 Valid、Dirty、Read/Write/Execute 权限位。为避免单级页表占用过多连续物理内存，现代架构（如 RISC-V Sv39）采用多级页表，仅按需分配活跃叶节点页表。由于页表存于主存会导致每次访存翻倍，CPU 内置转译后备缓冲器（TLB）作为页表的高速缓存。为隐藏地址翻译延迟，高速 L1 Cache 常采用“虚索引实标记”（VIPT）设计，使得 TLB 查找与 Cache 组索引并行执行，前提是 Cache 每一路的大小不能超过单个物理页的大小。", "template_cpp": "// RISC-V Sv39 三级页表虚拟地址拆分 (39位有效虚拟地址, 4KiB页)\nstruct Sv39Addr {\n    uint64_t vpn2, vpn1, vpn0, offset;\n};\nSv39Addr parse_sv39(uint64_t va) {\n    return {\n        (va >> 30) & 0x1FF, // 9 bits\n        (va >> 21) & 0x1FF, // 9 bits\n        (va >> 12) & 0x1FF, // 9 bits\n        va & 0xFFF          // 12 bits (4KiB)\n    };\n}", "pitfalls": "1. 误认为 TLB 失效一定触发缺页异常（Page Fault），实际上只要页表中该页 `Valid=1`，仅需硬件/软件遍历页表重填 TLB，耗时约数十周期而非毫秒级磁盘 I/O；2. 计算 VIPT Cache 约束时忘记考虑相联度：只要 $WaySize = \\frac{CacheSize}{Associativity} \\le PageSize$，Index 就完全落在 Page Offset 内部而无需等待 VPN 翻译，不存在别名问题。", "workbench_tags": ["虚拟内存", "多级页表", "TLB快表", "VIPT虚索引实标记"], "problems": [{"oj": "教材精选题", "pid": "COD-7.1", "title": "32位单级页表 vs 两级页表内存开销对比", "diff": "基础", "hint": "破题思路：32 位虚拟地址，页大小 $4\\text{ KiB}$，页表项（PTE）占 $4\\text{ B}$。\n解答要点：单级页表共有 $2^{32}/2^{12} = 2^{20}$ 项，每进程固定占用 $2^{20} \\times 4\\text{ B} = 4\\text{ MiB}$。采用两级页表（10+10+12 划分），若进程仅使用了 1 个代码页、1 个数据页和 1 个栈页（共占 3 个二级页表），只需 1 个顶级页目录（4 KiB）+ 3 个二级页表（$3 \\times 4\\text{ KiB}$），总计仅 $16\\text{ KiB}$。"}, {"oj": "教材精选题", "pid": "COD-7.2", "title": "TLB、Page Table 与 Cache 联合访存状态全组合判定", "diff": "中档", "hint": "破题思路：分析 TLB 命中/缺失、页表有效/缺页、Cache 命中/缺失 8 种组合中哪些在物理上不可能发生。\n解答要点：若 TLB 命中，则该页必然已在物理内存中（页表不可能缺页），故“TLB Hit + Page Fault”不可能发生；同样若发生“Page Fault”，该页不在主存中，也绝不可能存在于物理标记的 Cache 中，故“Page Fault + Cache Hit”也不可能发生。"}, {"oj": "教材精选题", "pid": "COD-7.3", "title": "VIPT L1 Cache 的最大无别名容量与相联度推导", "diff": "中档", "hint": "破题思路：系统页大小 $4\\text{ KiB}$，块大小 $64\\text{ B}$，欲设计无别名（No Aliasing）的 $32\\text{ KiB}$ VIPT L1 Cache，求最小相联度。\n解答要点：Page Offset 为 $\\log_2 4096 = 12\\text{ bits}$，Block Offset 为 $6\\text{ bits}$。为使 Index 完全取自 Page Offset，Index 最多占 $12 - 6 = 6\\text{ bits}$，即最多 $2^6 = 64$ 组。单路容量为 $64 \\times 64\\text{ B} = 4\\text{ KiB}$，故 $32\\text{ KiB}$ 至少需要 $32\\text{ KiB} / 4\\text{ KiB} = 8$ 路组相联。"}, {"oj": "教材精选题", "pid": "COD-7.4", "title": "TLB 命中率与缺页率对有效访存时间 EAT 的量化影响", "diff": "压轴", "hint": "破题思路：TLB 耗时 $1\\text{ ns}$（命中率 $99\\%$），主存耗时 $80\\text{ ns}$（二级页表需 2 次额外主存读），Cache 命中率 $100\\%$（为简化聚焦 TLB）下，若有 $0.0001\\%$ 的缺页率且缺页耗时 $10\\text{ ms} = 10^7\\text{ ns}$，求 EAT。\n解答要点：无缺页时 $T_{trans+mem} = 0.99\\times(1 + 80) + 0.01\\times(1 + 2\\times 80 + 80) = 80.19 + 2.41 = 82.6\\text{ ns}$。加上缺页惩罚 $10^{-6} \\times 10^7\\text{ ns} = 10\\text{ ns}$，EAT 飙升至 $92.6\\text{ ns}$，可见极低的缺页率也能主导系统延迟。"}]}, {"cid": "arch_ch8", "title": "第6章（上）存储、总线与 I/O：中断、DMA 与 RAID 冗余阵列", "summary": "本章阐述 CPU 与外部设备及海量存储介质的数据交互机制。I/O 控制方式经历了从 CPU 轮询（Polling，空转浪费周期）、中断驱动（Interrupt，按字节/字触发上下文切换）到直接内存访问（DMA，仅在整块传输开始与结束时中断 CPU）的演进；现代设备还普遍采用内存映射 I/O（MMIO）使设备寄存器如同普通内存地址被 `lw`/`sw` 访问。磁盘访问总延迟由寻道时间（Seek）、旋转延迟（平均半圈）与传输时间三部分构成。为兼顾性能与可靠性，磁盘阵列 RAID 采用条带化与奇偶校验技术：RAID 0 无冗余纯条带化、RAID 1 镜像冗余（50% 空间利用率）、RAID 5 分布式单奇偶校验（容忍 1 盘失效，避免校验盘写瓶颈），RAID 6 双校验容忍 2 盘同时失效。", "template_cpp": "// RAID 5 异或奇偶校验生成与单盘重建模板\n#include <vector>\n#include <cstdint>\nusing namespace std;\n\nuint8_t compute_parity(const vector<uint8_t>& disks) {\n    uint8_t p = 0;\n    for (uint8_t b : disks) p ^= b;\n    return p;\n}\n// 若 disk[k] 损坏，利用其余盘与校验盘异或即可无损恢复:\n// recovered = parity ^ (all remaining data disks)", "pitfalls": "1. 误认为 DMA 传输期间完全不占用总线，实则 DMA 控制器与 CPU 竞争系统总线（周期窃取 Cycle Stealing）及内存带宽；2. 计算 RAID 5 随机小写（Small Write）开销时误以为只需 1 次写，实际上更新 1 个数据块需“读旧数据、读旧校验、写新数据、写新校验”共 4 次 I/O（Write Penalty = 4）；3. 计算旋转延迟时忘记取平均旋转半圈（$0.5 / \\text{RPM} \\times 60\\text{ s}$）。", "workbench_tags": ["DMA直接内存访问", "MMIO内存映射", "RAID5写惩罚", "磁盘访问延迟"], "problems": [{"oj": "教材精选题", "pid": "COD-8.1", "title": "轮询、中断与 DMA 三种 I/O 方式 CPU 开销对比", "diff": "基础", "hint": "破题思路：1 GHz CPU 向速率 $10\\text{ MB/s}$ 的网卡发送数据包，每次轮询/中断处理耗 $400$ 周期（每 4B 触发一次），DMA 每 $4\\text{ KB}$ 仅需初始化与结束共 $1000$ 周期。\n解答要点：传输 $10\\text{ MB/s}$ 即每秒 $2.5\\times 10^6$ 个 4B 字。中断方式每秒消耗 $2.5\\times 10^6 \\times 400 = 10^9$ 周期，CPU 占用率达 $100\\%$；DMA 每秒仅 $10\\text{ MB} / 4\\text{ KB} = 2500$ 次块传输，消耗 $2500 \\times 1000 = 2.5 \\times 10^6$ 周期，CPU 占用率仅 $0.25\\%$。"}, {"oj": "教材精选题", "pid": "COD-8.2", "title": "7200 RPM 机械硬盘随机读 4KB 扇区平均耗时", "diff": "中档", "hint": "破题思路：已知平均寻道时间 $8\\text{ ms}$，转速 $7200\\text{ RPM}$，内部持续传输率 $120\\text{ MB/s}$。\n解答要点：平均旋转半圈时间 $= 0.5 \\times (60 / 7200)\\text{ s} = 4.167\\text{ ms}$；传输 $4\\text{ KB}$ 耗时 $= 4\\text{ KB} / 120\\text{ MB/s} \\approx 0.033\\text{ ms}$。总平均耗时 $= 8 + 4.167 + 0.033 = 12.2\\text{ ms}$，可见机械延迟远超数据传输本身。"}, {"oj": "教材精选题", "pid": "COD-8.3", "title": "RAID 0/1/5/6 容量利用率与写惩罚定量分析", "diff": "中档", "hint": "破题思路：共有 6 块 $4\\text{ TB}$ 硬盘，分别组建 RAID 0、RAID 10、RAID 5、RAID 6。\n解答要点：RAID 0 可用容量 $24\\text{ TB}$（容错 0 盘）；RAID 10 可用 $12\\text{ TB}$（每镜像对坏 1 盘共最多容错 3 盘，写惩罚 2）；RAID 5 可用 $(6-1)\\times 4 = 20\\text{ TB}$（容错 1 盘，随机小写惩罚 4）；RAID 6 可用 $(6-2)\\times 4 = 16\\text{ TB}$（容错 2 盘，随机小写惩罚 6）。"}, {"oj": "教材精选题", "pid": "COD-8.4", "title": "DMA 与 Cache 写入一致性的软件/硬件协同维护", "diff": "压轴", "hint": "破题思路：当 CPU 对写回（Write-Back）Cache 中的缓冲区写入数据后，立即启动 DMA 将该缓冲区从物理内存发往磁盘，分析隐患与对策。\n解答要点：隐患在于新数据可能仍滞留在 CPU 的 L1/L2 脏 Cache 块中而未写回主存，导致 DMA 读到旧数据（Stale Data）。对策：软件层面在启动 DMA 前显式执行 Cache Flush/Clean（写回脏块），或硬件层面采用 DMA 一致性协议（由 IOMMU/Coherency Interconnect 监听并直读 CPU Cache）。"}]}, {"cid": "arch_ch9", "title": "第6章（下）并行体系结构：缓存一致性、伪共享与 Roofline 模型", "summary": "本章探讨多核与数据级并行架构的核心挑战。基于 Flynn 分类法，SIMD/向量处理器（如 RISC-V RVV 扩展与 GPU）通过单指令流处理多数据流实现高吞吐；MIMD 多核共享内存架构则面临“缓存一致性”（Cache Coherence）问题——多个核心的私有 Cache 可能缓存同一物理地址的副本。监听协议（如 MESI：Modified, Exclusive, Shared, Invalid）利用总线广播确保任意时刻“多读或单写”不变式。此外，即使两线程修改互不重叠的独立变量，只要它们落入同一 64B Cache 行，就会引发“伪共享”（False Sharing），导致 Cache 行在核心间高频乒乓失效。最后，Roofline 模型以计算强度（OI，每字节访存对应的浮点运算次数）为横轴，将硬件瓶颈直观划分为受限于峰值带宽的“访存受限区”与受限于峰值算力的“计算受限区”。", "template_cpp": "// 伪共享消除：使用 alignas(64) 填充 Cache Line 对齐\n#include <atomic>\nstruct alignas(64) PaddedCounter {\n    std::atomic<long long> val{0};\n};\nPaddedCounter thread_counters[8]; // 每个核心独占独立的 64B Cache 行", "pitfalls": "1. 混淆“缓存一致性（Coherence，针对同一地址的读写可见顺序）”与“内存一致性模型（Memory Consistency，针对不同地址间的乱序重排，如 Store Buffer 导致的 Store-Load 乱序）”；2. 编写多线程直方图统计时把各线程计数器紧邻存放在普通数组 `cnt[tid]` 中，引发严重伪共享导致多核比单核更慢；3. 在 Roofline 模型中未考虑 Cache 复用而直接用原始数组大小估算算术强度。", "workbench_tags": ["MESI缓存一致性", "伪共享", "Roofline模型", "SIMD并行"], "problems": [{"oj": "教材精选题", "pid": "COD-9.1", "title": "MESI 协议在双核读写序列下的状态迁移追踪", "diff": "基础", "hint": "破题思路：假设变量 `x` 初始在主存，Core 0 和 Core 1 初始均无效（I）。操作序列：`1. Core 0 读 x; 2. Core 1 读 x; 3. Core 0 写 x; 4. Core 1 读 x`。\n解答要点：步 1：Core 0 读缺失，总线无其他副本，Core 0 变为 `E`（独占）；步 2：Core 1 读缺失，Core 0 嗅探到后将自己转为 `S`，Core 1 亦为 `S`；步 3：Core 0 写，发 `Invalidate` 使 Core 1 变为 `I`，Core 0 转为 `M`；步 4：Core 1 读缺失，Core 0 截获请求将数据写回主存/直传，双方均转为 `S`。"}, {"oj": "教材精选题", "pid": "COD-9.2", "title": "Roofline 模型脊点（Ridge Point）与算子瓶颈判定", "diff": "中档", "hint": "破题思路：某处理器峰值算力 $P_{peak} = 100\\text{ GFLOP/s}$，峰值内存带宽 $BW = 25\\text{ GB/s}$。评估稀疏矩阵向量乘（SpMV，计算强度 $OI = 0.25\\text{ FLOP/B}$）与稠密矩阵乘（GEMM，$OI = 16\\text{ FLOP/B}$）的上限性能。\n解答要点：脊点 $OI_{ridge} = P_{peak} / BW = 100 / 25 = 4\\text{ FLOP/B}$。SpMV 的 $OI = 0.25 < 4$，处于访存受限区，性能上限为 $0.25 \\times 25 = 6.25\\text{ GFLOP/s}$；GEMM 的 $OI = 16 > 4$，处于计算受限区，上限可达 $100\\text{ GFLOP/s}$。"}, {"oj": "教材精选题", "pid": "COD-9.3", "title": "伪共享（False Sharing）定位与结构体内存重排", "diff": "中档", "hint": "破题思路：64B Cache 行下，4 个线程分别高频累加 `int sum[4]`。\n解答要点：4 个 `int` 共占 16 字节，全部挤在同一个 64B Cache 行内。每次任一线程执行 `sum[tid]++` 都会使其他 3 核的该 Cache 行置为 `Invalid`，引发高频总线失效流量。解法：在线程内部用局部变量累加，结束时一次性写回；或将数组元素按 `alignas(64)` 填充至 64 字节间隔。"}, {"oj": "教材精选题", "pid": "COD-9.4", "title": "Store Buffer 引发的内存乱序与内存屏障（Fence）修复", "diff": "压轴", "hint": "破题思路：初始 `x = 0, y = 0`。Core 0 执行 `x = 1; r1 = y;`；Core 1 执行 `y = 1; r2 = x;`。在强一致 SC 模型下不可能出现 `r1=0 && r2=0`，但在现代 TSO（x86）或弱序（RISC-V）下却可能发生。\n解答要点：原因在于每核的写操作先进入私有 Store Buffer 尚未刷新到 L1 Cache，后续的读操作越过写缓冲直接读到了旧值。修复：在 `x = 1` 与 `r1 = y` 之间（以及 Core 1 对应位置）插入 RISC-V 内存屏障指令 `fence rw, rw`，强制先排空 Store Buffer 再执行后续读操作。"}]}]}, {"id": "gh_bupt_hw", "name": "🎓 北邮 CS 学长攻略（数电 / 计组 / 体系结构）", "author": "faranten/bupt-cs-gallery & Yokumii · GitHub", "level": "专业课横向整合 + 实验防坑", "repo_url": "https://github.com/faranten/bupt-cs-gallery", "chapters": [{"cid": "BUPT-HW-01", "title": "北邮电路、数字逻辑、计组与体系结构通关指南", "summary": "1) 电路与电子学基础：课时紧、前期容易一头雾水，好在期末考题友好，抓牢 KVL/KCL、戴维南等效与一阶 RC 三要素法即可稳过。2) 数字逻辑与数字系统：PPT 例题与编程/实验作业务必反复看，卡诺图化简与时序状态机设计非常套路。3) 计组与体系结构：典型专业课，不能只做题，必须【横向对比】（如不同 Cache 映射/写策略/流水线转发与分支预测的适用场景与局限），并在理解基础上记忆核心英文/中文概念；计组课设用 TEC-8 等硬件实验台注意流水线吞指令边界测试。", "template_cpp": "计组核心公式：CPI = 理想CPI + 停顿周期；AMAT = HitTime + MissRate × MissPenalty；Cache 地址划分 = [Tag | Index | Block Offset]。", "pitfalls": "只刷题不背概念；Cache 字节编址 vs 字编址时忘记扣掉 Byte Offset 位数。", "workbench_tags": ["北邮考情", "硬件体系"], "problems": []}]}];
window.__WB_CHEATSHEET__ = {"title": "计算机硬件与体系结构 · 考前1页纸速查卡", "sections": [{"heading": "一、数字逻辑、卡诺图与时序约束", "items": [{"name": "Setup Time 与 Hold Time 时序不等式", "formula": "$T_{\\text{clk}} \\ge t_{cq} + t_{\\text{comb,max}} + t_{\\text{su}} - t_{\\text{skew}},\\quad t_{cq,\\min} + t_{\\text{comb,min}} \\ge t_{\\text{hold}} + t_{\\text{skew}}$", "note": "正时钟偏斜 ($t_{\\text{skew}} > 0$) 放宽建立时间要求，但极易破坏保持时间导致 Hold Violation！"}, {"name": "Verilog 阻塞 (=) vs 非阻塞 (<=) 与 Latch", "formula": "$\\text{组合逻辑用 } =\\text{ 且覆盖全分支},\\quad \\text{时序逻辑 (always @(posedge clk)) 用 } \\le$", "note": "组合 always 块内 if 缺 else 或 case 缺 default 会意外综合出锁存器 (Latch)，引入毛刺与时序隐患。"}, {"name": "跨时钟域 (CDC) 与异步 FIFO", "formula": "$\\text{MTBF} = \\frac{e^{T_{\\text{res}}/\\tau}}{T_0 f_c f_d},\\quad \\text{异步 FIFO 深度 } = 2^k \\text{ 且指针转格雷码}$", "note": "单比特慢到快用两级触发器同步；多比特总线严禁直接打两拍，需用格雷码异步 FIFO 或握手信号。"}, {"name": "静态冒险检测与卡诺图消除", "formula": "$\\text{卡诺图两相邻 1 圈未相交} \\implies \\text{加冗余乘积项覆盖边界}$", "note": "单输入跳变时因反相器延迟出现毛刺；门控时钟 (Clock Gating) 必须用 Latch+AND 防毛刺。"}, {"name": "6-LUT 容量与加法器延迟", "formula": "$k\\text{-LUT 可实现任意 } k \\text{ 变量布尔函数 }(2^k\\text{ bit SRAM}),\\quad \\text{RCA } O(n)\\text{ vs CLA } O(\\log n)$", "note": "超前进位加法器 (CLA) 利用生成信号 $G_i=A_i B_i$ 与传播信号 $P_i=A_i \\oplus B_i$ 并行计算进位。"}]}, {"heading": "二、计算机算术、IEEE 754 与运算器", "items": [{"name": "补码表示范围与溢出判定", "formula": "$[-2^{n-1},\\ 2^{n-1}-1],\\quad \\text{OF} = C_n \\oplus C_{n-1} = (A_s \\odot B_s) \\land (S_s \\oplus A_s)$", "note": "符号位进位与最高数值位进位异或为 1 即溢出；无符号数溢出看最高位进位 CF。"}, {"name": "IEEE 754 单精度浮点数格式", "formula": "$(-1)^S \\times (1.M)_2 \\times 2^{E - 127}\\quad (1\\text{S}+8\\text{E}+23\\text{M},\\ \\text{Bias}=127)$", "note": "$E=0$ 为零或非规格化数（隐含位 0，指数 $-126$）；$E=255$ 且 $M=0$ 为 $\\pm\\infty$，$M\\neq 0$ 为 NaN。"}, {"name": "Booth 两位乘与 Wallace 树", "formula": "$\\text{Booth: } y_{i-1}-y_i \\in \\{-1,0,+1\\},\\quad \\text{3-2 压缩器 } (CSA) \\implies O(\\log n) \\text{ 级延迟}$", "note": "Booth 算法统一处理有符号补码乘法；保留进位加法器 (CSA) 延迟与位宽无关。"}, {"name": "海明码校验位与纠错公式", "formula": "$2^r \\ge k + r + 1\\quad (\\text{纠 1 位错}),\\quad \\text{SEC-DED 需再加 1 位总奇偶校验}$", "note": "校验位放在 $2^0, 2^1, 2^2,\\dots$ 位置，出错位号等于所有奇偶校验失败位下标之和。"}, {"name": "大小端序与移位区别", "formula": "$\\text{Little-Endian: 低字节存低地址},\\quad \\text{算术右移补符号位，逻辑右移补 } 0$", "note": "C/C++ 负数右移通常为算术右移，但负数左移及移位位数 $\\ge$ 位宽属于未定义行为。"}]}, {"heading": "三、RISC-V 架构与处理器设计", "items": [{"name": "RV32I 六种基本指令编码格式", "formula": "$\\text{R/I/S/B/U/J 型均 32 位定长},\\quad \\text{opcode}=[6:0],\\ \\text{rd}=[11:7],\\ \\text{rs1}=[19:15]$", "note": "rs1/rs2/rd 位置跨格式固定，译码器可在解析 opcode 的同时并行读取寄存器堆。"}, {"name": "立即数拼接与符号扩展规则", "formula": "$\\text{B 型偏移低位补 0 (2B 对齐)},\\quad \\text{J 型 } \\pm 1\\text{MB},\\quad \\text{U 型 } \\text{imm}[31:12]\\ll 12$", "note": "所有立即数最高位 (inst[31]) 均为符号位，方便硬件直接扇出符号扩展。"}, {"name": "单周期 vs 多周期 vs 流水线时钟周期", "formula": "$T_{\\text{single}} = \\sum_{i=1}^5 t_i,\\quad T_{\\text{pipe}} = \\max_i t_i + t_{\\text{reg}}$", "note": "单周期 CPI=1 但时钟受最慢指令 (lw) 限制；流水线提高吞吐率但单条指令延迟略增。"}, {"name": "RISC-V 调用约定 (ABI) 寄存器角色", "formula": "$\\text{x0}=0,\\ \\text{x1}=\\text{ra},\\ \\text{x2}=\\text{sp},\\ \\text{a0-a7 传参},\\ \\text{s0-s11 被调用者保存 (Callee-saved)}$", "note": "t0-t6 与 a0-a7 为调用者保存 (Caller-saved)；函数调用前若还要用 t 寄存器需自行压栈。"}, {"name": "精确异常 (Precise Exception) 处理", "formula": "$\\text{冲刷异常指令及之后指令},\\quad \\text{mepc} \\leftarrow \\text{PC},\\ \\text{mcause} \\leftarrow \\text{原因}$", "note": "乱序处理器依赖重排序缓冲区 (ROB) 按序提交，确保异常前指令全部生效、之后指令全未提交。"}]}, {"heading": "四、流水线与指令级并行 (ILP)", "items": [{"name": "流水线加速比与吞吐率", "formula": "$S_k = \\frac{n \\cdot k}{k + n - 1} \\xrightarrow{n \\to \\infty} k,\\quad \\text{CPI}_{\\text{real}} = \\text{CPI}_{\\text{ideal}} + \\text{Stall}_{\\text{data}} + \\text{Stall}_{\\text{ctrl}}$", "note": "5 级流水线（IF-ID-EX-MEM-WB）中，前半周期写寄存器、后半周期读寄存器可消除 WB→ID 结构/数据冒险。"}, {"name": "Load-Use 数据冒险与旁路 (Forwarding)", "formula": "$\\text{EX/MEM} \\to \\text{EX 零气泡},\\quad \\text{lw 后紧跟使用指令必须停顿 } 1 \\text{ 拍 (Bubble)}$", "note": "EX 阶段结束才能从数据 Cache 读出 lw 结果，无法旁路回同一拍的 EX，只能插 1 个气泡或编译器指令调度。"}, {"name": "控制冒险与动态分支预测", "formula": "$\\text{Branch Penalty} = \\text{MissRate} \\times \\text{MispredictCycles},\\quad \\text{BTB + 2-bit 饱和计数器 / TAGE}$", "note": "2-bit 饱和计数器需连续两次预测错误才翻转状态，显著降低循环末尾的分支误预测。"}, {"name": "Tomasulo 算法与寄存器重命名", "formula": "$\\text{消除 WAW (输出相关) 与 WAR (反相关)},\\quad \\text{保留站 (RS) + CDB 广播}$", "note": "只有真数据相关 (RAW) 不可消除；RAT 将架构寄存器映射到物理寄存器 PRF/ROB 槽位。"}, {"name": "阿姆达尔定律 (Amdahl's Law)", "formula": "$S_{\\text{overall}} = \\frac{1}{(1 - f) + \\frac{f}{s}}$", "note": "可加速比例 $f$ 决定了总加速比的极限上限 $\\frac{1}{1-f}$；优化应聚焦占执行时间大头的热点。"}]}, {"heading": "五、存储系统、虚拟内存与总线 I/O", "items": [{"name": "Cache 映射与组相联地址划分", "formula": "$\\text{Index} = \\log_2\\left(\\frac{\\text{CacheSize}}{\\text{BlockSize} \\times \\text{Ways}}\\right),\\quad \\text{Tag} = \\text{AddrBits} - \\text{Index} - \\text{Offset}$", "note": "VIPT (虚索引实标签) 若 $\\text{Index}+\\text{Offset} \\le \\text{PageOffset}$ (如 4KB 页下 $64\\text{B}\\times 64\\text{组}$)，可实现 TLB 与 Cache 并行查找且无别名问题。"}, {"name": "Write-Through vs Write-Back", "formula": "$\\text{Write-Back + Write-Allocate: 需 Dirty 位，替换脏块时才写回下级}$", "note": "Write-Through 常配 Write Buffer 与 No-Write-Allocate；现代 L1/L2/L3 普遍采用写回+写分配。"}, {"name": "3C 失效模型与优化手段", "formula": "$\\text{Compulsory (冷启动)} + \\text{Capacity (容量)} + \\text{Conflict (冲突)}$", "note": "增大块大小降 Compulsory（但增惩罚），增大相联度降 Conflict，硬件预取降 Compulsory/Capacity。"}, {"name": "多核 MESI 缓存一致性协议", "formula": "$\\text{Modified / Exclusive / Shared / Invalid},\\quad \\text{写 Shared 块需发 BusRdX/Invalidate}$", "note": "总线嗅探 (Snooping) 适合小核数，大规模多核采用基于目录 (Directory-based) 的点对点一致性。"}, {"name": "I/O 传输：中断 vs DMA 占用率", "formula": "$\\text{DMA 仅在传输开始前配置与结束后中断一次 CPU},\\quad \\text{周期窃取 (Cycle Stealing)}$", "note": "DMA 与 Cache 同时存在可能引发一致性问题（需软件刷 Cache 或硬件 I/O 一致性）。"}]}, {"heading": "六、并行架构与未来计算体系", "items": [{"name": "Flynn 分类与 Roofline 模型", "formula": "$\\text{Attainable Perf} = \\min(\\text{Peak FLOPs},\\ \\text{Peak BW} \\times \\text{AI}),\\quad \\text{AI} = \\frac{\\text{FLOPs}}{\\text{Bytes}}$", "note": "算术强度 $\\text{AI}$ 低于拐点为访存受限 (Memory-bound)，高于拐点为计算受限 (Compute-bound)。"}, {"name": "GPU SIMT 架构与 Warp 分化", "formula": "$\\text{Warp}=32\\text{ 线程锁步执行},\\quad \\text{分支分化时串行执行各路径并用掩码屏蔽}$", "note": "共享内存 (Shared Memory) 划分为 32 个 Bank，同一 Warp 访问同一 Bank 不同地址会产生 Bank Conflict。"}, {"name": "脉动阵列 (Systolic Array) 与 TPU", "formula": "$\\text{N}\\times\\text{N 阵列表明 } O(N^2)\\text{ MAC 仅需 } O(N)\\text{ 边界访存}$", "note": "数据流经相邻 PE 复用（Weight-Stationary 或 Output-Stationary），极大降低矩阵乘能耗。"}, {"name": "内存一致性模型：SC vs TSO", "formula": "$\\text{TSO (x86): 允许 Store-Load 乱序 (Store Buffer)},\\quad \\text{ARM/RISC-V: 弱序需显式 fence}$", "note": "Store Buffer 导致经典的 Dekker/Peterson 算法在现代 CPU 上失效，需插入 mfence/dmb 指令。"}, {"name": "硬件安全微架构侧信道", "formula": "$\\text{Spectre (分支预测越界投机)} \\land \\text{Meltdown (乱序越权读核)} + \\text{Flush+Reload}$", "note": "投机执行虽不提交架构状态，但会留下 Cache 痕迹；防护包括 KPTI 页表隔离与 retpoline。"}]}, {"heading": "七、高频易错点与考场避坑清单", "items": [{"name": "时钟偏斜 (Clock Skew) 对 Setup/Hold 的相反作用", "formula": "$\\text{正偏斜: } t_{\\text{su}}\\text{ 变松, } t_{\\text{hold}}\\text{ 变紧};\\quad \\text{负偏斜: } t_{\\text{su}}\\text{ 变紧, } t_{\\text{hold}}\\text{ 变松}$", "note": "Hold Time 违例与时钟周期 $T_{\\text{clk}}$ 无关，降频无法修复 Hold 违例，只能插 Buffer 增最小延迟！"}, {"name": "Cache Tag 总位数别忘加有效位与脏位", "formula": "$\\text{SRAM 总开销} = \\text{行数} \\times (\\text{Valid } 1\\text{b} + \\text{Dirty } 1\\text{b} + \\text{LRU位} + \\text{Tag} + \\text{DataBits})$", "note": "算“Cache 总容量”通常指数据区大小，算“SRAM 实际总位数”必须把 Tag/Valid/Dirty/LRU 全部加进去。"}, {"name": "平均访存时间 (AMAT) 的多级递推", "formula": "$\\text{AMAT} = t_{L1} + \\text{MR}_{L1} \\times (t_{L2} + \\text{MR}_{L2} \\times t_{\\text{mem}})$", "note": "注意题目给的是 Local Miss Rate（基于到达 L2 的请求）还是 Global Miss Rate（基于总访存请求）。"}, {"name": "虚拟地址 vs 物理地址在 TLB/Cache 中的流转", "formula": "$\\text{先查 TLB 得 PPN} \\to \\text{拼接物理页偏移得 PA} \\to \\text{查物理 Cache}$", "note": "TLB 命中不代表 Cache 命中，TLB 缺失也不代表缺页（页表仍在内存，只有 Valid=0 才 Page Fault）。"}, {"name": "RISC-V 分支偏移单位是字节而非指令数", "formula": "$\\text{Target PC} = \\text{PC} + \\text{sign\\_ext}(\\text{imm}\\_{\\text{B/J}})$", "note": "RISC-V 偏移以字节为单位（隐含最低位为 0），与 MIPS 按字（4B）左移 2 位不同。"}]}]};
